const orders = $json.orders || [];
const body = $('Orders Webhook').item.json.body || {};
const requestedEmail = (body.email || '').toString().toLowerCase().trim();
const requestedNumber = (body.order_number || body[''] || '').toString().trim();

// Neutral answer: identical whether the order does not exist or the details do not match.
const noMatch = [{ json: {
  found: false,
  result: "No matching order for these details. Ask the customer to check the order number and the email address."
}}];

const normalize = v => (v || '').toString().trim().replace(/^#/, '').toLowerCase();

// Both identifiers must match the same order, otherwise nothing is disclosed.
const o = orders.find(x =>
  normalize(x.name) === normalize(requestedNumber) &&
  requestedEmail !== '' &&
  (x.email || '').toString().toLowerCase().trim() === requestedEmail
);
if (!o) return noMatch;

const fulfillments = o.fulfillments || [];
const trackingNumbers = fulfillments.flatMap(f =>
  (f.tracking_numbers && f.tracking_numbers.length > 0) ? f.tracking_numbers : (f.tracking_number ? [f.tracking_number] : [])
).filter(Boolean);
const trackingUrls = fulfillments.flatMap(f =>
  (f.tracking_urls && f.tracking_urls.length > 0) ? f.tracking_urls : (f.tracking_url ? [f.tracking_url] : [])
).filter(Boolean);
const carriers = [...new Set(fulfillments.map(f => f.tracking_company).filter(Boolean))];

// Data minimization: no name, no address, no phone, no email is returned to the model.
const formatted = {
  name: o.name,
  created_at: o.created_at,
  created_at_display: new Date(o.created_at).toLocaleDateString('en-US'),
  days_since_order: Math.floor((Date.now() - new Date(o.created_at).getTime()) / 86400000),
  financial_status: o.financial_status,
  fulfillment_status: o.fulfillment_status || 'unfulfilled',
  carriers,
  tracking_numbers: trackingNumbers,
  tracking_urls: trackingUrls,
  items: (o.line_items || []).map(i => ({ name: i.name, qty: i.quantity }))
};

const statusLabels = {'pending':'Pending','paid':'Paid','refunded':'Refunded','voided':'Voided','partially_refunded':'Partially refunded'};
const fulfLabels = {'unfulfilled':'Being prepared','fulfilled':'Shipped','partial':'Partially shipped'};
const s = statusLabels[formatted.financial_status] || formatted.financial_status;
const f = fulfLabels[formatted.fulfillment_status] || 'Being prepared';
const it = formatted.items.map(i => `${i.name} x${i.qty}`).join(', ');
const result = `${formatted.name} - ${formatted.created_at_display}\nProducts: ${it}\nPayment: ${s}\nShipping: ${f}`
  + (carriers.length ? `\nCarrier: ${carriers.join(', ')}` : '')
  + (trackingNumbers.length ? `\nTracking: ${trackingNumbers.join(', ')}` : '')
  + (trackingUrls.length ? `\nLink: ${trackingUrls[0]}` : '');

return [{ json: { found: true, order: formatted, result } }];
